import { DomainError } from './errors';

export type TaskStatusValue = 'todo' | 'in progress' | 'done';

export class TaskStatus {
  private static readonly values: readonly TaskStatusValue[] = ['todo', 'in progress', 'done'];

  private constructor(public readonly value: TaskStatusValue) {}

  public static create(value: string): TaskStatus {
    if (!TaskStatus.values.includes(value as TaskStatusValue)) {
      throw new DomainError('Status must be todo, in progress, or done');
    }
    return new TaskStatus(value as TaskStatusValue);
  }

  public static todo(): TaskStatus {
    return new TaskStatus('todo');
  }

  public isDone(): boolean {
    return this.value === 'done';
  }
}

