import { ConflictError, DomainError } from './errors';
import { TaskStatus } from './task-status';

export class Task {
  public constructor(
    public readonly id: string,
    public readonly projectId: string,
    public readonly title: string,
    public readonly description: string,
    public readonly dueDate: Date | undefined,
    public readonly assigneeId: string | undefined,
    private status: TaskStatus,
  ) {
    if (!id.trim() || !projectId.trim() || !title.trim() || !description.trim()) {
      throw new DomainError('Task id, project id, title, and description are required');
    }
    if (dueDate !== undefined && Number.isNaN(dueDate.getTime())) {
      throw new DomainError('Due date must be a valid date');
    }
  }

  public getStatus(): TaskStatus {
    return this.status;
  }

  public markDone(): void {
    if (this.status.isDone()) {
      throw new ConflictError('Task is already done');
    }
    this.status = TaskStatus.create('done');
  }
}

